#include <memory>
#include <string>
#include <utility>

class IMovement
{
public:
    virtual ~IMovement() = default;
    virtual std::string move() const = 0;
};

class Walk : public IMovement { public: std::string move() const override { return "walks"; } };
class Fly : public IMovement { public: std::string move() const override { return "flies"; } };
class Swim : public IMovement { public: std::string move() const override { return "swims"; } };

class Robot
{
public:
    Robot(std::string name, std::unique_ptr<IMovement> movement) : m_name{ std::move(name) }, m_movement{ std::move(movement) } {}

    void setMovement(std::unique_ptr<IMovement> movement) { m_movement = std::move(movement); }

    std::string act() const
    {
        return m_name + " " + (m_movement ? m_movement->move() : "stands still");
    }

private:
    std::string m_name{};
    std::unique_ptr<IMovement> m_movement{};
};

unitTests:
static_assert(std::is_abstract_v<IMovement> && std::has_virtual_destructor_v<IMovement>);
struct Roll : IMovement { std::string move() const override { return "rolls"; } };

TEST("acts according to its movement") { const Robot r{ "R2", std::make_unique<Walk>() }; CHECK_EQ(r.act(), "R2 walks"); }
TEST("behaviour can be swapped at run time") { Robot r{ "Bee", std::make_unique<Walk>() }; r.setMovement(std::make_unique<Fly>()); CHECK_EQ(r.act(), "Bee flies"); r.setMovement(std::make_unique<Swim>()); CHECK_EQ(r.act(), "Bee swims"); }
TEST("new behaviours need no change to Robot") { const Robot r{ "BB8", std::make_unique<Roll>() }; CHECK_EQ(r.act(), "BB8 rolls"); }
TEST("no movement") { Robot r{ "Rock", nullptr }; CHECK_EQ(r.act(), "Rock stands still"); r.setMovement(std::make_unique<Walk>()); r.setMovement(nullptr); CHECK_EQ(r.act(), "Rock stands still"); }

